with q as (
 select * from (values
 ('pcac-2026-lc129-transgressoes-penalidades-responsabilidades','pcac-disc-pen-01','LC nº 129/2004 — grupos e penalidades','Segundo o material, qual é o limite máximo de suspensão para transgressão disciplinar do segundo grupo?','(A) 15 dias.\n(B) 30 dias.\n(C) 60 dias.\n(D) 90 dias.\n(E) 120 dias.','C','O art. 109, conforme a redação apresentada, limita a suspensão a 60 dias para transgressão do segundo grupo. O teto de 90 dias é relativo ao terceiro grupo.'),
 ('pcac-2026-lc129-transgressoes-penalidades-responsabilidades','pcac-disc-pen-02','LC nº 129/2004 — responsabilidades','Conforme o art. 106-C citado no material, as responsabilidades civil, penal e administrativa:','(A) São sempre alternativas, nunca cumulativas.\n(B) Podem cumular-se e são independentes entre si.\n(C) Dependem todas de condenação criminal.\n(D) São aplicadas exclusivamente pelo Delegado-Geral.\n(E) Produzem sempre a mesma penalidade.','B','O art. 106-C prevê a possibilidade de cumulação e a independência das esferas civil, penal e administrativa.'),
 ('pcac-2026-lc129-deveres-investigacao-e-processo-disciplinar','pcac-disc-deveres-01','LC nº 129/2004 — representação funcional','Segundo o art. 100, parágrafo único, a representação contra ilegalidade, omissão ou abuso de poder deve ser:','(A) Encaminhada diretamente à imprensa.\n(B) Arquivada sem apreciação.\n(C) Encaminhada pela via hierárquica e apreciada por autoridade superior àquela contra quem foi formulada, assegurada ampla defesa.\n(D) Decidida exclusivamente pelo próprio representado.\n(E) Feita apenas oralmente.','C','O material reproduz o fluxo previsto no parágrafo único do art. 100: via hierárquica, apreciação por autoridade superior e ampla defesa ao representado.'),
 ('pcac-2026-lc129-deveres-investigacao-e-processo-disciplinar','pcac-disc-deveres-02','LC nº 129/2004 — PAD obrigatório','Quando o processo administrativo disciplinar é obrigatório, segundo o art. 129 apresentado no material?','(A) Em toda falta funcional, sem exceção.\n(B) Quando a infração, por sua natureza, puder determinar demissão a bem do serviço público.\n(C) Apenas quando houver denúncia anônima.\n(D) Somente depois de condenação criminal.\n(E) Quando o servidor pedir transferência.','B','O art. 129 determina a obrigatoriedade do PAD quando a natureza da infração puder determinar demissão a bem do serviço público.'),
 ('pcac-2026-lc129-pad-instrucao-defesa-relatorio-recursos','pcac-disc-pad-01','LC nº 129/2004 — defesa e provas','Após o interrogatório, qual prazo o material indica para o acusado requerer ou apresentar provas?','(A) 48 horas.\n(B) 5 dias.\n(C) 10 dias.\n(D) 15 dias.\n(E) 30 dias.','C','O material indica 10 dias após o interrogatório para requerer ou apresentar provas, podendo o acusado arrolar até oito testemunhas.'),
 ('pcac-2026-lc129-pad-instrucao-defesa-relatorio-recursos','pcac-disc-pad-02','LC nº 129/2004 — citação','Qual é a antecedência mínima indicada no material para a citação pessoal do acusado no PAD?','(A) 12 horas.\n(B) 24 horas.\n(C) 48 horas.\n(D) 5 dias.\n(E) 10 dias.','C','A citação pessoal deve ocorrer com antecedência mínima de 48 horas, acompanhada de cópia da portaria com motivo e enquadramento legal.'),
 ('pcac-2026-lc129-sindicancia-prazos-prescricao-extincao','pcac-disc-sindic-01','LC nº 129/2004 — sindicância','Qual é o prazo de conclusão da sindicância indicado no art. 127 do material?','(A) 10 dias, improrrogáveis.\n(B) 15 dias, prorrogáveis por 15.\n(C) 30 dias, prorrogáveis mediante solicitação fundamentada.\n(D) 60 dias, prorrogáveis por 60.\n(E) 90 dias, improrrogáveis.','C','O material indica 30 dias contados da portaria inaugural ou auto de constatação, prorrogáveis mediante solicitação fundamentada à autoridade que determinou a abertura.'),
 ('pcac-2026-lc129-sindicancia-prazos-prescricao-extincao','pcac-disc-sindic-02','LC nº 129/2004 — prescrição','Segundo o material, qual é o prazo prescricional para falta sujeita à pena de advertência?','(A) 30 dias.\n(B) 180 dias.\n(C) 1 ano.\n(D) 2 anos.\n(E) 5 anos.','B','O art. 118, conforme apresentado no material, prevê seis meses para falta sujeita a advertência. Seis meses correspondem a aproximadamente 180 dias, mas memorize a unidade de tempo usada na lei.'),
 ('pcac-2026-lc39-deveres-acumulacao-penalidades-prescricao-pad','pcac-disc-lc39-01','LC nº 39/1993 — prescrição','Na LC nº 39/1993, conforme o art. 193 apresentado no material, a ação disciplinar por infração punível com advertência prescreve em:','(A) 30 dias.\n(B) 90 dias.\n(C) 180 dias.\n(D) 1 ano.\n(E) 2 anos.','C','O art. 193 prevê 180 dias para advertência, dois anos para suspensão e cinco anos para demissão e hipóteses equiparadas.'),
 ('pcac-2026-lc39-deveres-acumulacao-penalidades-prescricao-pad','pcac-disc-lc39-02','LC nº 39/1993 — acumulação','Mesmo quando a acumulação remunerada de cargos públicos é constitucionalmente permitida, qual condição deve ser comprovada segundo o art. 168, § 2º?','(A) Autorização verbal do superior.\n(B) Compatibilidade de horários.\n(C) Tempo mínimo de dez anos no serviço público.\n(D) Aprovação em novo concurso para cada vínculo.\n(E) Residência no mesmo município.','B','A acumulação lícita depende da comprovação de compatibilidade de horários. A exceção constitucional não elimina essa condição.')
 ) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation)
)
